#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int n;        cin >> n;         int neg = 0;        for (int i = 0; i < n; i++) {            int x;            cin >> x;            if (x == -1) neg++;        }         int pos = n - neg;        int sum = pos - neg;        int ops = 0;         // Step 1: fix sum (make sum >= 0)        if (sum < 0) {            int need = (-sum + 1) / 2; // ceil((-sum)/2)            ops += need;            neg -= need;   // flipped -1 to 1            pos += need;        }         // Step 2: fix product (number of -1 must be even)        if (neg % 2 == 1) {            ops++;        }         cout << ops << "\n";    }    return 0;}